6	
7	/** Top-level directory -> backend. See the "Storage split" table in docs/12-storage/overview.md. */
8	const INDEXEDDB_DIRECTORIES = new Set(["projects", "settings", "thumbnails", "waveforms"]);
9	const OPFS_DIRECTORIES = new Set(["assets", "models", "voice-cache", "exports"]);
