11	function topLevelDirectory(path: string): string {
12	  const segment = path.split("/", 1)[0];
13	  if (!segment) {
14	    throw new Error(`Invalid VFS path: "${path}"`);
15	  }
16	  return segment;
17	}
18	
19	export interface IStorageEngineDependencies {
20	  indexedDb?: IStorageAdapter;
21	  opfs?: IStorageAdapter;
22	}
23	
24	/**
25	 * The only module that talks to actual browser storage. Implements IVFS by
26	 * routing each path to IndexedDB or OPFS based on its top-level directory —
27	 * every other engine depends on IVFS, never on IndexedDBAdapter/OpfsAdapter
28	 * directly. See docs/12-storage/overview.md.
29	 */
30	export class StorageEngine implements IEngine, IVFS {
31	  readonly name = "Storage";
32	
33	  private readonly indexedDb: IStorageAdapter;
34	  private readonly opfs: IStorageAdapter;
35	
36	  constructor(dependencies: IStorageEngineDependencies = {}) {
